cd $TMPDIR; for r in $(ls -td rfq-run-*/ | head -25); do python3 - "$r" <<'EOF'
import json,sys,glob,os
r=sys.argv[1]; files=glob.glob(r+'**/session.jsonl',recursive=True)
if not files: sys.exit()
st=dict(read_url=0,read_urls=0,read_urls_pages=0,read_here=0,fetch_like=0,fl_values=0,nav=0,click=0)
for f in files:
  for l in open(f):
    if not l.startswith('{'): continue
    d=json.loads(l)
    if d.get('type')!='assistant': continue
    for b in d['message'].get('content',[]):
      if b.get('type')!='tool_use': continue
      n=b['name']; i=b['input']
      if n.endswith('web__read'):
        if i.get('urls'): st['read_urls']+=1; st['read_urls_pages']+=len(i['urls'])
        elif i.get('url'): st['read_url']+=1
        else: st['read_here']+=1
      elif n.endswith('fetch_like'): st['fetch_like']+=1; st['fl_values']+=len(i.get('values',[]))
      elif n.endswith('browser_navigate'): st['nav']+=1
      elif n.endswith('browser_click'): st['click']+=1
print(os.path.basename(r.rstrip('/')), sorted(os.listdir(r))[:3], st)
EOF
done

