async def fetch(site: str, urls: list[str], links: bool = True) -> str:
    """Read pages by address over the site's own login, without opening them: much faster than navigating or
    clicking. Give addresses you saw as links (absolute or relative to the site; up to 20 at once). Each page comes
    back as text the way a user sees it, with its links (text -> address), so you can follow them with another call.
    Only for reading: never for forms, searches that need a button, gates, or anything that saves, confirms or sends.
    On sites where fetched pages differ from what the browser shows, pages are opened in background tabs instead
    (slower, same result). A page that comes back FAILED: open it in the browser."""
    targets = [clean_url(urljoin(SITES.get(site, "") + "/", u)) for u in urls[:20]]
    mode = await calibrate(site)
    sem = _sem.setdefault(site, asyncio.Semaphore(PARALLEL))

    async def one(u: str) -> str:
        if mode == "fetch":
            async with sem:
                data = await raw_fetch(site, u)
            problem = fetch_problem(data, u)
            for f in (data.get("frames") or [])[:3]:
                if site_of(f) == site:
                    async with sem:
                        sub = await raw_fetch(site, f)
                    if not fetch_problem(sub, f):
                        data["text"] += f"\n[frame {f}]\n" + sub["text"]
                        data["links"] += sub.get("links", [])
            if problem is None:
                visited[site].add(clean_url(u))
                return compact(site, data, 0, links)
        data = await render(site, u)
        if data.get("error"):
            return f"## {u}\nFAILED: {data['error']} - open it in the browser instead"
        if data.get("password"):
            return f"## {u}\nFAILED: a login page (session expired?) - log in again in the browser"
        return compact(site, data, 0, links)

    return "\n\n".join(await asyncio.gather(*(one(u) for u in targets)))


