cat > /Users/simon/hackathon/urltest/gate_audit.py <<'EOF'
"""For each site session of a run: which kinds of page were batch-fetched in browser_evaluate scripts, and whether a
page of that kind was opened in the browser before the first fetch (the 'open one first' rule). A kind = the path
without its last segment / query values, e.g. /messages/MSG-1 -> /messages/."""
import json, os, re, sys, glob
from urllib.parse import urlparse

def kind(path: str) -> str:
    path = path.split("?")[0]
    path = re.sub(r"\$\{[^}]*\}", "X", path)
    parts = [p for p in path.split("/") if p]
    return "/" + "/".join(parts[:-1]) + "/" if len(parts) > 1 else "/" + (parts[0] if parts else "") + "?"

for run in sys.argv[1:]:
    print(f"== {run}")
    for f in sorted(glob.glob(os.path.join(run, "site-*", "session.jsonl"))):
        site = f.split("site-")[1].split("/")[0]
        rows = [json.loads(l) for l in open(f) if l.startswith("{")]
        res = {}
        for d in rows:
            if d.get("type") == "user" and isinstance(d.get("message", {}).get("content"), list):
                for b in d["message"]["content"]:
                    if b.get("type") == "tool_result":
                        c = b.get("content")
                        res[b["tool_use_id"]] = c if isinstance(c, str) else json.dumps(c)
        seen, report = set(), {}
        for d in rows:
            if d.get("type") != "assistant":
                continue
            for b in d["message"].get("content", []):
                if b.get("type") != "tool_use":
                    continue
                out = res.get(b["id"], "")
                for u in re.findall(r"Page URL: (\S+)", out):
                    seen.add(kind(urlparse(u).path + ("?" + urlparse(u).query if urlparse(u).query else "")))
                if b["input"].get("url"):
                    pass
                code = b["input"].get("function") or b["input"].get("code") or ""
                if b["name"].endswith(("browser_evaluate", "browser_run_code_unsafe")) and "fetch(" in code:
                    for u in re.findall(r"""['"`]((?:/|https?://)[^'"`\s]{1,120})""", code):
                        p = urlparse(u).path if u.startswith("http") else u
                        k = kind(p)
                        report.setdefault(k, "opened first" if k in seen else "NOT opened in browser first")
        for k, v in report.items():
            print(f"  {site:16} {k:45} {v}")
EOF
