p,run=sys.argv[1],sys.argv[2]
def ts(d): return datetime.datetime.fromisoformat(d['timestamp'].replace('Z','+00:00'))
def load(site):
    try: return [json.loads(l) for l in open(f"{p}/site-{site}/session.jsonl") if l.startswith('{')]
    except FileNotFoundError: return []
erp=load('erp'); cust=load('customer-portal')
if not erp: sys.exit()
t0=min(ts(d) for d in erp if 'timestamp' in d)
# when customer portal saved revisions
rev=None
for d in cust:
    if d.get('type')=='assistant':
        for b in d['message'].get('content',[]):
            if b.get('type')=='tool_use' and b['name'].endswith('record') and b['input'].get('kind')=='revisions':
                rev=rev or ts(d)
