    res={}
    for d in rows:
        if d.get('type')=='user' and isinstance(d.get('message',{}).get('content'),list):
            for b in d['message']['content']:
                if b.get('type')=='tool_result':
                    x=b.get('content'); res[b['tool_use_id']]=x if isinstance(x,str) else json.dumps(x)
    for d in rows:
        if d.get('type')!='assistant': continue
        for b in d['message'].get('content',[]):
            if b.get('type')=='tool_use' and b['name'].endswith(('browser_click','browser_drag','browser_type','browser_fill_form','browser_select_option','browser_press_key')):
                out=res.get(b['id'],'')
                m=re.search(r"getBy(Role|Text|Label)\('?([a-z]*)'?,?\s*(\{ name: '([^']*)')?", out)
                n=b['name'].split('__')[-1]
                if n!='browser_click': kind=n.replace('browser_','')
                elif m and m.group(1)=='Role': kind=m.group(2)
                elif m: kind='text:'+m.group(1)
