                label=(m.group(4) if m and m.group(4) else '')[:35]
                if len(ex[kind])<4: ex[kind].append(f"{site}:{label}")
print('==', sys.argv[1], sum(c.values()), 'non-navigation actions')
for k,v in c.most_common(): print(f'  {k:16} {v:3}  e.g. {ex[k]}')
EOF
done

